import Foundation

struct StackViewModel {
    private let dStack:  DStack
    private let minStack: MinStack
    private let maxStack: MaxStack
    
    init(minStack: MinStack = .init(),
         dStack: DStack = .init(),
         maxStack: MaxStack = .init()) {
        self.minStack = minStack
        self.dStack = dStack
        self.maxStack = maxStack
    }
    func minStackOperation() {
        minStack.push(-2)
        minStack.push(0)
        minStack.push(-3)
        
        print("\(minStack.getMin())") //  // return -3)
        minStack.pop();
        
        print("\(minStack.top())") // 0
        print("\(minStack.getMin())") //  // return -2)
    }
    func lruCache() {
        let cache = LRUCache(2)
        cache.put(1, 1)      // cache = {1=1}
        cache.put(2, 2)      // cache = {1=1, 2=2}
        print(cache.get(1))  // 1 -> moves key=1 to head
        cache.put(3, 3)      // evicts key=2, cache = {1=1, 3=3}
        print(cache.get(2))  // -1 (not found)
        cache.put(4, 4)      // evicts key=1, cache = {3=3, 4=4}
        print(cache.get(1))  // -1
        print(cache.get(3))  // 3
        print(cache.get(4))  // 4
    }
    func evalRPN() {
        
    }
    func carFleet() {
        print(dStack.ST2_853_carFleet(12, [10,8,0,5,3], [2,4,1,1,3])) // Output: 3
        print(dStack.ST2_853_carFleet(10, [3], [3]))                 // Output: 1
        print(dStack.ST2_853_carFleet(100, [0,2,4], [4,2,1]))        // Output: 1
    }
    func minRemoveToMakeValid() {
        print(dStack.ST3_1249_minRemoveToMakeValid("lee(t(c)o)de)"))  // "lee(t(c)o)de"
        print(dStack.ST3_1249_minRemoveToMakeValid("a)b(c)d"))        // "ab(c)d"
        print(dStack.ST3_1249_minRemoveToMakeValid("))(("))           // ""
        print(dStack.ST3_1249_minRemoveToMakeValid("(a(b(c)d)"))      // "a(b(c)d)"
    }
    func largestRectangleArea() {
        print(dStack.S5_84_largestRectangleArea([2,1,5,6,2,3])) // 10
        print(dStack.S5_84_largestRectangleArea([2,4]))        // 4
        print(dStack.S5_84_largestRectangleArea([6,2,5,4,5,1,6])) // 12
    }
    func longestValidParentheses() {
        print(dStack.S6_32_longestValidParentheses_1("(()"))      // 2
        print(dStack.S6_32_longestValidParentheses_1(")()())"))  // 4
        print(dStack.S6_32_longestValidParentheses_1(""))        // 0
        print(dStack.S6_32_longestValidParentheses_1("()(())"))  // 6
    }
    
    func S7_716_MaxStack() {
        let maxStack = MaxStack()
        maxStack.push(5)
        maxStack.push(1)
        maxStack.push(5)

        print(maxStack.top())     // 5
        print(maxStack.popMax())  // 5
        print(maxStack.top())     // 1
        print(maxStack.peekMax()) // 5
        print(maxStack.pop())     // 1
        print(maxStack.top())     // 5

    }
